-- V90.dd — Production Machine Integration + IoT Foundation
CREATE TABLE IF NOT EXISTS machine_iot_device(device_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,device_code TEXT NOT NULL,device_type TEXT NOT NULL,protocol TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,device_code));
CREATE TABLE IF NOT EXISTS machine_iot_telemetry(telemetry_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,device_id TEXT NOT NULL,parameter_code TEXT NOT NULL,value NUMERIC NOT NULL,unit TEXT,event_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,quality TEXT NOT NULL DEFAULT 'GOOD',source TEXT NOT NULL DEFAULT 'MACHINE',created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS machine_iot_state(state_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,device_id TEXT NOT NULL,state_code TEXT NOT NULL,event_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,derived BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS machine_iot_threshold(threshold_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,device_id TEXT NOT NULL,parameter_code TEXT NOT NULL,min_value NUMERIC,max_value NUMERIC,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,UNIQUE(organization_id,entity_id,device_id,parameter_code));
CREATE TABLE IF NOT EXISTS machine_iot_alert(alert_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,device_id TEXT NOT NULL,parameter_code TEXT NOT NULL,value NUMERIC NOT NULL,alert_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',telemetry_id TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_iot_telemetry_scope ON machine_iot_telemetry(organization_id,entity_id,work_center_id,device_id,event_at);
